shared.ax:
export contract positive(value: u32) -> u32 {
 requires value > 0;
 ensures result == value;
}
export contract liar(value: u32) -> u32 {
 ensures result == value +% 1;
}

root_a.ax:
import { positive } from "./shared.ax";
export contract alpha(value: u32) -> u32 {
 requires value > 0;
 requires positive(value) == positive(value);
 ensures result == positive(value);
}

root_b.ax:
import { positive } from "./shared.ax";
export contract beta(value: u32) -> u32 {
 requires value > 0;
 ensures result == positive(value);
}

unsafe.ax:
import { positive } from "./shared.ax";
export contract unsafe_root(value: u32) -> u32 {
 ensures result == positive(value);
}

failed.ax:
import { liar } from "./shared.ax";
export contract depends_on_failed(value: u32) -> u32 {
 ensures result == liar(value);
}

entry.ax:
import { alpha } from "./root_a.ax";
import { beta } from "./root_b.ax";
import { unsafe_root } from "./unsafe.ax";
import { depends_on_failed } from "./failed.ax";
contract entry(value: u32) -> u32 {
 requires value > 0;
 ensures result == value;
}
